{
  "probability": 0.02,
  "range_low": 0.01,
  "range_high": 0.04,
  "summary": [
    "Starting from a low base-rate anchor around 12% from formal forecasts for a one-year horizon.",
    "Multiple updates push the posterior downward due to normative constraints, ongoing monitoring, and attribution uncertainty.",
    "Signals of chemical agents on the battlefield exist but attribution and verification remain contested, yielding a modest final probability.",
    "Overall calibration acknowledges non-zero risk but maintains a low probability before May 1, 2026."
  ],
  "confidence": "low",
  "narrative": "The reference-class anchor sits at about 12% for state-on-state chemical-weapons use within a year. After accounting for escalation signals, strong deterrence, and OPCW monitoring with attribution uncertainty, the calibrated posterior probability falls to 2%, reflecting substantial uncertainty and the enduring norms against chemical warfare.",
  "justification": {
    "anchor": {
      "probability": 0.12,
      "basis": "Reference class is forecasts of chemical/biological weapons use in interstate conflict with a one-year horizon (Russia–Ukraine war). The Swift Centre and Metaculus place a median near 12%, providing a defensible anchor for this question."
    },
    "factor_updates": [
      {
        "factor": "Escalation risk in the Russia–Ukraine war increasing coercive signaling",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Intensified fighting could raise incentives to consider chemical options as coercive tools, nudging probability upward."
      },
      {
        "factor": "OPCW monitoring and attribution uncertainty",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Active monitoring and lack of clear attribution reduce confidence in imminent, state-sponsored use, pulling probability downward."
      },
      {
        "factor": "Documented use/incidents of riot-control agents (CS) on battlefield",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "CS detections signal chemical-agent presence and raise the plausibility of further state involvement, pushing probability up."
      },
      {
        "factor": "Historical base-rate and global norm against interstate chemical-weapon use",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Strong norms and the Chemical Weapons Convention historically suppress the likelihood of use, pulling probability down."
      },
      {
        "factor": "International deterrence and potential sanctions on an actor state",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Expected consequences increase costs and reduce the attractiveness of chemical-weapons use, contributing to a downward revision."
      }
    ],
    "synthesis_rationale": "Starting from a 12% anchor, we apply a mix of up and down updates reflecting escalation signals, battlefield CS evidence, deterrence, and monitoring with attribution uncertainty. The net effect, given the weight of deterrence and verification against contested signals, yields a low posterior of 2%. Calibration notes acknowledge data limitations, attribution uncertainty, and ongoing monitoring, which keep the probability non-zero but modest."
  }
}

{
  "probability": 0.02,
  "range_low": 0.01,
  "range_high": 0.05,
  "summary": [
    "Anchor based on a 12% forecast for chemical/biological weapon use within 12 months in the Russia–Ukraine war.",
    "New battlefield detections of riot-control agents (CS) and intelligence signals raise the near-term risk modestly.",
    "OPCW monitoring, international norms, and deterrence weigh strongly downward, yielding a low overall probability before May 1, 2026.",
    "Attribution uncertainty and verification limits keep the risk non-zero but subdued."
  ],
  "confidence": "low",
  "narrative": "Bayesian updating yields a posterior probability of 2% for any state actor using chemical weapons in Ukraine before May 1, 2026. Upward signals from CS detections and increased Russian chemical activity are tempered by strong norms, monitoring, and attribution uncertainty, producing a low-probability forecast with substantial uncertainty around the exact likelihood.",
  "justification": {
    "anchor": {
      "probability": 0.12,
      "basis": "Swift Centre forecast for a 12% probability of chemical/biological weapon use in the next 12 months within the Russia–Ukraine war."
    },
    "factor_updates": [
      {
        "factor": "Documented use/incidents of riot-control agents (CS) in Ukraine",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "OPCW-confirmed CS on the battlefield signals non-zero risk and potential for state involvement, nudging probability upward."
      },
      {
        "factor": "Intelligence assessments of increased Russian chemical-agent use",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Dutch/German intelligence reports suggest higher usage of banned agents, elevating risk of future state use."
      },
      {
        "factor": "OPCW monitoring and verification; ongoing protection measures",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Continued monitoring and adherence to CWC norms dampen risk by enabling deterrence and rapid attribution."
      },
      {
        "factor": "Longstanding norms and sanctions risk; deterrence",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Global norms against chemical weapons and potential sanctions raise the cost of use, lowering probability."
      },
      {
        "factor": "Forecast anchors and uncertainty about future events",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Forecasts show a wide range; the uncertainty supports caution in posterior calibration."
      }
    ],
    "synthesis_rationale": "The 12% anchor is tempered by credible downweights from norms, deterrence, and monitoring, while upweights from CS detections and intensified Russian chemical activity are present but not decisive due to attribution uncertainties and ongoing verification. The net effect, after Bayesian updating, is a low posterior around 2%, with uncertainty bands spanning roughly 1–5%."
  }
}

